import{_ as o,o as s,c as t,ae as d}from"./chunks/framework.YL6nI5ZP.js";const i="/docs/assets/simulation-pipeline.BT_6BHdG.png",u=JSON.parse('{"title":"The Simulation Pipeline and the WASM Engine Bridge","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/02-simulation-pipeline.md","filePath":"explanation/02-simulation-pipeline.md"}'),a={name:"explanation/02-simulation-pipeline.md"};function r(n,e,c,l,p,h){return s(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="the-simulation-pipeline-and-the-wasm-engine-bridge" tabindex="-1">The Simulation Pipeline and the WASM Engine Bridge <a class="header-anchor" href="#the-simulation-pipeline-and-the-wasm-engine-bridge" aria-label="Permalink to &quot;The Simulation Pipeline and the WASM Engine Bridge&quot;">​</a></h1><p>How a simulation flows from the UI to the engine and back — the workers, the message contracts, and the WASM bridge that connects JavaScript to the C++ engine.</p><h2 id="end-to-end-flow" tabindex="-1">End-to-end flow <a class="header-anchor" href="#end-to-end-flow" aria-label="Permalink to &quot;End-to-end flow&quot;">​</a></h2><p>Pressing <strong>Run</strong> (<code>#btn-run</code>, <code>ui.js:216</code>) walks this path:</p><p><img src="'+i+'" alt="Simulation pipeline"></p><p>The two backends share the same run surface but differ in fidelity: the WASM engine is the reference (f64, faithful), while the WebGPU marcher is an opt-in performance path (<code>Net.useGpu2d === true</code>) that re-implements the 2D explicit local-inertial solver on the GPU.</p><h2 id="pre-flight-validation" tabindex="-1">Pre-flight validation <a class="header-anchor" href="#pre-flight-validation" aria-label="Permalink to &quot;Pre-flight validation&quot;">​</a></h2><p><code>runSimulation</code> (<code>app.js:1392-1489</code>) aborts with a warning if: no nodes; no <code>OUTFALL</code>; or a 2D mesh is present while units are US (<code>app.js:1402-1406</code> — 2D is SI-only).</p><h2 id="duration-estimate-cosmetic-progress" tabindex="-1">Duration estimate (cosmetic progress) <a class="header-anchor" href="#duration-estimate-cosmetic-progress" aria-label="Permalink to &quot;Duration estimate (cosmetic progress)&quot;">​</a></h2><p><code>estimateSimDurationMs(inpText, networkSize)</code> (<code>app.js:1083-1129</code>) parses <code>[OPTIONS]</code> START/END and <code>ROUTING_STEP</code> from the INP and extrapolates wall-clock time. The 1D Run-Status progress bar is driven by a <code>setInterval</code> against this estimate, capped at 99% then asymptoting to 100% (<code>app.js:1252-1271</code>).</p><h2 id="web-workers" tabindex="-1">Web Workers <a class="header-anchor" href="#web-workers" aria-label="Permalink to &quot;Web Workers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Worker</th><th>Instantiated at</th><th>Role</th></tr></thead><tbody><tr><td><code>parseWorker.js</code></td><td><code>app.js:933</code> (per import)</td><td>Parse <code>.inp</code> text off-thread</td></tr><tr><td><code>simWorker.js</code></td><td><code>app.js:969-978</code> (<strong>persistent</strong>)</td><td>1D engine run; pre-warmed at load (<code>app.js:1304</code>)</td></tr><tr><td><code>openSwmm2dWorker.js</code></td><td><code>app.js:1143</code> (per 2D run)</td><td>1D+2D coupled engine + frame sampling (<strong>default — the f64 reference</strong>)</td></tr><tr><td><code>webgpu/gpu2dWorker.js</code></td><td><code>app.js:1186</code> (per 2D run, <strong>only if <code>Net.useGpu2d === true</code></strong>)</td><td>WebGPU f32 marcher (opt-in performance path)</td></tr></tbody></table><p><strong>Worker message contracts</strong> (main → worker):</p><ul><li><code>parseWorker</code>: <code>{ text }</code> → posts <code>{type:&#39;progress&#39;|&#39;done&#39;, model}</code> | <code>{type:&#39;error&#39;}</code>.</li><li><code>simWorker</code>: <code>{ type:&#39;run&#39;, inpText, targetDurationMs, files? }</code> → posts <code>{type:&#39;ready&#39;}</code> (once, after wasm compile), <code>{type:&#39;log&#39;|&#39;err&#39;}</code>, <code>{type:&#39;done&#39;, rpt, outBuffer}</code> (transferable ArrayBuffer), <code>{type:&#39;error&#39;}</code>.</li><li><code>openSwmm2dWorker</code> / <code>gpu2dWorker</code>: <code>{ type:&#39;run2d&#39;, inp, triangleIds, meshFile|null, triangleVertices, dryDepth, wantVertexFields, frameIntervalMs }</code> (+ optional transferred <code>wasmBinary</code>) → posts <code>{type:&#39;status2d&#39;, stage}</code>, <code>{type:&#39;stdout&#39;|&#39;stderr&#39;}</code>, <code>{type:&#39;progress2d&#39;, elapsedMs}</code>, <code>{type:&#39;results2d&#39;, triangleIds, frames, diagnostics, report}</code> (buffers transferred), <code>{type:&#39;error&#39;}</code>.</li></ul><p><strong>Worker lifecycle asymmetry:</strong> the 1D worker is created once and reused (<code>simWorker.onerror</code> nulls it so the next run recreates it); the 2D workers are recreated every run and a failed WASM instance cannot be reused (<code>openSwmm2dWorker.js:376</code>).</p><p><strong>Stop:</strong> <code>stopSimulationWorker()</code> (<code>app.js:1038-1059</code>) terminates both workers, clears the fake-progress timer, and restores the Run button.</p><h2 id="_1d-vs-2d-execution-inside-the-engine" tabindex="-1">1D vs 2D execution inside the engine <a class="header-anchor" href="#_1d-vs-2d-execution-inside-the-engine" aria-label="Permalink to &quot;1D vs 2D execution inside the engine&quot;">​</a></h2><ul><li><strong><code>simWorker.js</code></strong> — 1D-only blocking runner: writes one <code>.inp</code> to MEMFS, calls <code>stride(engine, 10_000_000, …)</code> once to run to completion, reads <code>/rpt.rpt</code> and <code>/out.out</code>, transfers the bytes. No frame sampling (<code>simWorker.js:76-81</code>).</li><li><strong><code>openSwmm2dWorker.js</code></strong> — 1D+2D runner: same lifecycle but advances in <code>stride(…, stepsPerYield=256)</code> chunks and <strong>samples per-triangle frames in JS between strides</strong> (<code>readFrame</code>, <code>openSwmm2dWorker.js:158-179</code>) — this is what produces the 2D animation timeline. Also reads 2D diagnostics (mass balance, solver steps, max velocity) and the report. No <code>.out</code> parsing on this path.</li><li><strong><code>webgpu/gpu2dWorker.js</code></strong> — same <code>results2d</code> contract, but the 2D advance runs on the GPU marcher (see the 2D mesh &amp; WebGPU subsystem) instead of the WASM solver.</li></ul><h2 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h2><p><strong><code>.out</code> binary parser — <code>swmmOutParser.js</code>:</strong> reads the SWMM output-file footer (last six INT32s: <code>idNamesOffset, objPropsOffset, resultsOffset, numPeriods, errCode, magicEnd</code>), validates magic <code>516114522</code>, parses headers and variable counts, and exposes <strong>zero-copy <code>Float32Array</code> views</strong> over period records (<code>readResults</code>, <code>swmmOutParser.js:132-180</code>). Hot paths: <code>getTimeSeries(type,index,varIndex)</code> (cached, <code>:184-209</code>) and <code>getStepData(type,step,varIndex)</code> for per-step map coloring (<code>:212-230</code>).</p><p><strong>Presentation — <code>results.js</code>:</strong> <code>.rpt</code> text is parsed once into summary tables (<code>parseNodeDepths</code>, <code>parseLinkFlows</code>, <code>parseFlooding</code>, <code>parseNodeInflows</code>, <code>parseOutfallLoadings</code>, <code>parseConduitSurcharges</code>, <code>parseSubcatchmentRunoffs</code>, <code>parseContinuityErrors</code>, <code>parseEngineErrors</code>, <code>parseTimeSeries</code> — <code>results.js:59-366</code>). <code>ResultStyling</code> (<code>results.js:369-547</code>) owns coloring: <code>applyToMapForStep(step)</code> (<code>:402-518</code>) paints 2D mesh frames first, then the optimized binary <code>.out</code> path, then the <code>.rpt</code> fallback. <code>displayResults</code> (<code>:790-1288</code>) builds KPI cards, continuity chips, color legends, sortable/filterable result tables with <code>IntersectionObserver</code> lazy sparklines, and fly-to-on-click. <code>display2DResults</code> (<code>:1291-1492</code>) colors the mesh per frame, exposes a depth/head/velocity selector, and drives the same time slider via a synthetic time series.</p><p><strong>Plotting:</strong> <code>profile.js</code> <code>ProfilePlot.openForNodes</code> (<code>:630</code>) BFS-traces conduits, samples terrain, and draws a hydraulic profile (capacity color coding: red ≥1.0 surcharged, amber ≥0.85, cyan normal). <code>plot.js</code> <code>TimeSeriesPlot</code> (<code>:227</code>) charts multi-series time series from binary <code>.out</code> (preferred) or <code>.rpt</code> fallback.</p><h2 id="the-shipped-binaries" tabindex="-1">The shipped binaries <a class="header-anchor" href="#the-shipped-binaries" aria-label="Permalink to &quot;The shipped binaries&quot;">​</a></h2><p><code>public/</code> contains <strong>two identical engine builds</strong> (same factory, same size 4,614,086 bytes, same stamp):</p><ul><li><code>openswmm2d.js</code> + <code>openswmm2d.wasm</code> — used by <code>openSwmm2dWorker.js</code>, <code>gpu2dWorker.js</code>, and all <code>scripts/*.mjs</code>.</li><li><code>swmm6wasm.js</code> + <code>swmm6wasm.wasm</code> — a copy used by <code>simWorker.js</code> (legacy name).</li></ul><p>Both are 2-line Emscripten glue exporting the factory <strong><code>createOpenSwmm2D</code></strong> (<code>swmm6wasm.js:1-2</code>). The <code>.version.json</code> files record the engine commit/describe/date (written by the build script).</p><h2 id="module-instantiation" tabindex="-1">Module instantiation <a class="header-anchor" href="#module-instantiation" aria-label="Permalink to &quot;Module instantiation&quot;">​</a></h2><p>The wasm is <strong>compiled once, instantiated per run</strong> (~10–50 ms per re-instantiation, per <code>simWorker.js:8-12</code>):</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// simWorker.js:19-63 (condensed)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> module</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WebAssembly.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">compileStreaming</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;swmm6wasm.wasm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// once</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> factory</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createOpenSwmm2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ noInitialRun: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    instantiateWasm</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">imports</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">cb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WebAssembly.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">instantiate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">module</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, imports).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">then</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> cb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(m.instance)) });</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> engine</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> factory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// fresh instance each run</span></span></code></pre></div><p><code>wasm/openswmm2d_exports.cpp</code> is deliberately <strong>source-only</strong> (6 lines): it includes the engine&#39;s public headers and nothing else, so Emscripten exports the C API as library functions without pulling in <code>main</code>/run lifecycle.</p><h2 id="exported-c-api-31-symbols-in-exported-functions" tabindex="-1">Exported C API (31 symbols in <code>EXPORTED_FUNCTIONS</code>) <a class="header-anchor" href="#exported-c-api-31-symbols-in-exported-functions" aria-label="Permalink to &quot;Exported C API (31 symbols in `EXPORTED_FUNCTIONS`)&quot;">​</a></h2><p><strong>Lifecycle</strong> (<code>swmm_engine_*</code>; state machine <code>CREATED → OPENED → INITIALIZED → STARTED → [RUNNING] → ENDED → CLOSED</code> per <code>openswmm_engine.h:31-37</code>):</p><table tabindex="0"><thead><tr><th>Symbol</th><th>Meaning</th></tr></thead><tbody><tr><td><code>swmm_engine_create</code> / <code>destroy</code></td><td>Allocate / free the engine handle</td></tr><tr><td><code>swmm_engine_open(engine, inp, rpt, out, plugin)</code></td><td>Parse the <code>.inp</code> (+ optional plugin lib, always <code>0</code> in wasm)</td></tr><tr><td><code>swmm_engine_initialize</code> / <code>start</code> / <code>end</code> / <code>close</code></td><td>Lifecycle transitions (<code>start</code> takes <code>save_results</code>)</td></tr><tr><td><code>swmm_engine_step(engine, double* elapsed)</code></td><td>Advance exactly one routing step</td></tr><tr><td><code>swmm_engine_stride(engine, n_steps, double* elapsed)</code></td><td>Advance up to <code>n</code> steps in one call</td></tr><tr><td><code>swmm_engine_report(engine)</code></td><td>Write the summary report file</td></tr></tbody></table><p><strong>2D accessors</strong> (<code>swmm_2d_*</code>): <code>swmm_2d_triangle_count</code>, <code>swmm_2d_get_depths_bulk</code>, <code>swmm_2d_get_heads_bulk</code>, <code>swmm_2d_get_stat_max_velocities</code>, <code>swmm_2d_get_continuity_error</code>, <code>swmm_2d_get_solver_steps</code> (+ legacy <code>swmm_2d_get_cvode_steps</code>), <code>swmm_2d_get_mass_balance</code> (10 double terms), and optional vertex/edge accessors (<code>swmm_2d_vertex_count</code>, <code>swmm_2d_vertex_get_xyz_bulk</code>, <code>swmm_2d_edge_get_geometry_bulk</code>, <code>swmm_2d_get_edge_flux_bulk</code>, <code>swmm_2d_vertex_get_render_depths_bulk</code>, <code>swmm_2d_vertex_get_heads_bulk</code>).</p><p><strong>1D node access/control</strong> (<code>swmm_node_*</code>): <code>swmm_node_count</code>, <code>swmm_node_get_heads/depths/volumes_bulk</code>, <code>swmm_node_set_lateral_inflow</code>, <code>swmm_node_set_pond_area</code> — used by the WebGPU split to feed 1D↔2D exchange back into the engine.</p><p>Plus <code>malloc</code>/<code>free</code> for JS↔wasm memory management.</p><h2 id="js-wrapper-layer-—-openswmm2dworker-js" tabindex="-1">JS wrapper layer — <code>openSwmm2dWorker.js</code> <a class="header-anchor" href="#js-wrapper-layer-—-openswmm2dworker-js" aria-label="Permalink to &quot;JS wrapper layer — `openSwmm2dWorker.js`&quot;">​</a></h2><ul><li><code>bindApi(Module)</code> (<code>:79-107</code>) wraps every symbol with <code>Module.cwrap</code>; <code>optional()</code> returns <code>null</code> for symbols absent from a build, so one worker handles multiple engine configurations.</li><li><code>check(code, op, Module, reportPath, payload)</code> (<code>:109-148</code>) throws rich errors; on failure it dumps the <code>.rpt</code> (filtered error lines or last 1500 chars) and the first 3000 chars of the INP as <code>stderr</code> messages — this is your first stop when a simulation &quot;fails silently&quot;.</li><li><code>readFrame(Module, api, engine, count, elapsedMs)</code> (<code>:158-179</code>) mallocs depth/head/velocity arrays, bulk-reads them, returns Float64Arrays, frees in <code>finally</code>.</li><li><code>readVelocity(...)</code> (<code>:196-229</code>) reconstructs <strong>cell-centered physical velocity</strong> from edge flux + edge geometry via a least-squares solve of <code>(NᵀN)v = Nᵀq</code> (q = flux/length), converting specific discharge to velocity (<code>/h</code>); dry cells (<code>h ≤ dryDepth</code>) are zeroed.</li><li><code>readDiagnostics(...)</code> (<code>:231-257</code>) reads mass balance, solver internal steps, max-velocity stats.</li><li><code>run(payload)</code> (<code>:259-368</code>) is the 2D run loop: write <code>/model2d.inp</code> (+ optional mesh file) → lifecycle <code>open→initialize→start</code> with <code>check()</code> after each → <code>do/while</code> <code>stride(engine, 256, …)</code> sampling frames at <code>frameIntervalMs</code> → final frame + diagnostics → <code>end→report</code> → post <code>results2d</code>.</li></ul><h2 id="memory-management" tabindex="-1">Memory management <a class="header-anchor" href="#memory-management" aria-label="Permalink to &quot;Memory management&quot;">​</a></h2><ul><li>All pointers come from <code>Module._malloc(bytes)</code> and are freed with <code>Module._free(ptr)</code>; scalar reads use <code>Module.getValue(ptr, &#39;double&#39;|&#39;i32&#39;)</code>; the code never touches raw HEAP views directly.</li><li>Files go to the Emscripten MEMFS virtual filesystem: <code>FS.writeFile(&#39;/in.inp&#39;, inpText)</code>, <code>FS.readFile(&#39;/rpt.rpt&#39;, {encoding:&#39;utf8&#39;})</code>, <code>FS.readFile(&#39;/out.out&#39;)</code> returning a <code>Uint8Array</code> <strong>view on the wasm heap</strong>. The worker slices a copy out (<code>outBytes.buffer.slice(...)</code>, <code>simWorker.js:162</code>) so the heap buffer can be detached on transfer.</li><li>2D worker unlinks its temp files in <code>finally</code> (<code>openSwmm2dWorker.js:364-366</code>).</li></ul>',40)])])}const g=o(a,[["render",r]]);export{u as __pageData,g as default};
